12	export const handleTraceSpanCount = ({
13	  assertion,
14	  assertionValueContext,
15	}: AssertionParams): GradingResult => {
16	  if (!assertionValueContext.trace || !assertionValueContext.trace.spans) {
17	    throw new Error('No trace data available for trace-span-count assertion');
18	  }
19	
20	  const value = assertion.value as TraceSpanCountValue;
21	  if (!value || typeof value !== 'object' || !value.pattern) {
22	    throw new Error('trace-span-count assertion must have a value object with pattern property');
23	  }
24	
25	  const { pattern, min, max } = value;
26	  const spans = assertionValueContext.trace.spans as TraceSpan[];
27	
28	  // Count spans matching the pattern
29	  const matchingSpans = spans.filter((span) => matchesPattern(span.name, pattern));
30	  const count = matchingSpans.length;
31	
32	  // Check against constraints
33	  let pass = true;
34	  let reason = '';
35	
36	  if (min !== undefined && count < min) {
37	    pass = false;
38	    reason = `Found ${count} spans matching pattern "${pattern}", expected at least ${min}`;
39	  } else if (max !== undefined && count > max) {
40	    pass = false;
41	    reason = `Found ${count} spans matching pattern "${pattern}", expected at most ${max}`;
42	  } else {
43	    reason = `Found ${count} spans matching pattern "${pattern}"`;
44	    if (min !== undefined && max !== undefined) {
45	      reason += ` (expected ${min}-${max})`;
46	    } else if (min !== undefined) {
47	      reason += ` (expected at least ${min})`;
48	    } else if (max !== undefined) {
49	      reason += ` (expected at most ${max})`;
50	    }
51	  }
52	
53	  // Add matched span names for debugging
54	  if (matchingSpans.length > 0) {
55	    const spanNames = [...new Set(matchingSpans.map((s) => s.name))];
56	    reason += `. Matched spans: ${spanNames.join(', ')}`;
57	  }
58	
59	  return {
60	    pass,
61	    score: pass ? 1 : 0,
62	    reason,
63	    assertion,
64	  };
65	};
