3	import type { AssertionParams, GradingResult } from '../types/index';
4	import type { TraceSpan } from '../types/tracing';
5	
6	interface TraceErrorSpansValue {
7	  max_count?: number;
8	  max_percentage?: number;
9	  pattern?: string;
10	}
11	
12	function isErrorSpan(span: TraceSpan): boolean {
13	  // Check various ways a span might indicate an error
14	  if (span.statusCode && span.statusCode >= 400) {
15	    return true;
16	  }
17	
18	  // Check for error-related attributes
19	  if (span.attributes) {
20	    // Common attribute names that might indicate errors
21	    const errorKeys = ['error', 'exception', 'failed', 'failure'];
22	    for (const key of errorKeys) {
23	      if (
24	        span.attributes[key] === true ||
25	        span.attributes[key] === 'true' ||
26	        (typeof span.attributes[key] === 'object' && span.attributes[key] !== null)
27	      ) {
28	        return true;
29	      }
30	    }
31	
32	    // Check for HTTP status codes in attributes (handle both string and number types)
33	    const httpStatusCode = span.attributes['http.status_code'];
34	    if (httpStatusCode !== undefined && httpStatusCode !== null) {
35	      const statusCodeNum = Number(httpStatusCode);
36	      if (!isNaN(statusCodeNum) && statusCodeNum >= 400) {
37	        return true;
38	      }
39	    }
40	
41	    // Check for OTEL standard error attributes
42	    if (
43	      span.attributes['otel.status_code'] === 'ERROR' ||
44	      span.attributes['status.code'] === 'ERROR'
45	    ) {
46	      return true;
47	    }
48	  }
49	
50	  // Check status message for error indicators
51	  if (span.statusMessage) {
52	    const errorPatterns = /error|failed|failure|exception|timeout|abort/i;
53	    if (errorPatterns.test(span.statusMessage)) {
54	      return true;
55	    }
56	  }
57	
58	  return false;
59	}
