61	export const handleTraceErrorSpans = ({
62	  assertion,
63	  assertionValueContext,
64	}: AssertionParams): GradingResult => {
65	  if (!assertionValueContext.trace || !assertionValueContext.trace.spans) {
66	    throw new Error('No trace data available for trace-error-spans assertion');
67	  }
68	
69	  const value = assertion.value;
70	  let maxCount: number | undefined;
71	  let maxPercentage: number | undefined;
72	  let pattern = '*';
73	
74	  // Handle simple number value for backwards compatibility
75	  if (typeof value === 'number') {
76	    maxCount = value;
77	  } else if (
78	    value &&
79	    typeof value === 'object' &&
80	    !Array.isArray(value) &&
81	    typeof value !== 'function'
82	  ) {
83	    const objValue = value as TraceErrorSpansValue;
84	    maxCount = objValue.max_count;
85	    maxPercentage = objValue.max_percentage;
86	    pattern = objValue.pattern || '*';
87	  }
88	
89	  if (maxCount === undefined && maxPercentage === undefined) {
90	    maxCount = 0; // Default to no errors allowed
91	  }
92	
93	  const spans = assertionValueContext.trace.spans as TraceSpan[];
94	
95	  // Filter spans by pattern
96	  const matchingSpans = spans.filter((span) => matchesPattern(span.name, pattern));
97	
98	  if (matchingSpans.length === 0) {
99	    return {
100	      pass: true,
101	      score: 1,
102	      reason: `No spans found matching pattern "${pattern}"`,
103	      assertion,
104	    };
105	  }
106	
107	  // Find error spans
108	  const errorSpans = matchingSpans.filter(isErrorSpan);
109	  const errorCount = errorSpans.length;
110	  const errorPercentage = (errorCount / matchingSpans.length) * 100;
111	
112	  let pass = true;
113	  let reason = '';
114	
115	  if (maxCount !== undefined && errorCount > maxCount) {
116	    pass = false;
117	    const errorDetails = errorSpans.slice(0, 3).map((span) => {
118	      let detail = span.name;
119	      if (span.statusMessage) {
120	        detail += ` (${span.statusMessage})`;
121	      } else if (span.statusCode) {
122	        detail += ` (status: ${span.statusCode})`;
123	      }
124	      return detail;
125	    });
126	
127	    reason = `Found ${errorCount} error spans, expected at most ${maxCount}. `;
128	    reason += `Errors: ${errorDetails.join(', ')}`;
129	    if (errorSpans.length > 3) {
130	      reason += ` and ${errorSpans.length - 3} more`;
131	    }
132	  } else if (maxPercentage !== undefined && errorPercentage > maxPercentage) {
133	    pass = false;
134	    reason = `Error rate ${errorPercentage.toFixed(1)}% exceeds threshold ${maxPercentage}% `;
135	    reason += `(${errorCount} errors out of ${matchingSpans.length} spans)`;
136	  } else {
137	    if (errorCount === 0) {
138	      reason = `No errors found in ${matchingSpans.length} spans matching pattern "${pattern}"`;
139	    } else {
140	      reason = `Found ${errorCount} error(s) in ${matchingSpans.length} spans (${errorPercentage.toFixed(1)}%)`;
141	      if (maxCount !== undefined) {
142	        reason += `, within threshold of ${maxCount}`;
143	      }
144	      if (maxPercentage !== undefined) {
145	        reason += `, within threshold of ${maxPercentage}%`;
146	      }
147	    }
148	  }
149	
150	  return {
151	    pass,
152	    score: pass ? 1 : 0,
153	    reason,
154	    assertion,
155	  };
156	};
