          assertion,
        };
      }
    } catch (err) {
      return {
        ...fail(
          `trajectory:goal-success produced malformed response: ${err}\n\n${resp.output}`,
          resp.tokenUsage,
        ),
        assertion,
      };
    }
  } else if (typeof resp.output === 'object') {
    jsonObjects = [resp.output];
  } else {
    return {
      ...fail(
